import json
import re
from decimal import Decimal, InvalidOperation

import pandas as pd
import pdfplumber
from rapidfuzz import fuzz, process

VENDORS_PATH = '/root/vendors.xlsx'
PO_PATH = '/root/purchase_orders.csv'
PDF_PATH = '/root/invoices.pdf'
OUT_PATH = '/root/fraud_report.json'


def norm_name(s: str) -> str:
    s = (s or '').lower().strip()
    s = re.sub(r'[^a-z0-9\s]', ' ', s)
    s = re.sub(r'\s+', ' ', s).strip()
    # light business-token normalization
    s = re.sub(r'\bltd\b', 'limited', s)
    s = re.sub(r'\binc\b', 'incorporated', s)
    s = re.sub(r'\bcorp\b', 'corporation', s)
    s = re.sub(r'\bco\b', 'company', s)
    s = re.sub(r'\s+', ' ', s).strip()
    return s


def norm_iban(s: str) -> str:
    return re.sub(r'\s+', '', (s or '')).upper()


def parse_money(s: str):
    if not s:
        return None
    s = s.strip()
    s = s.replace('$', '').replace('€', '').replace('£', '')
    s = s.replace(' ', '')
    # handle thousands separators
    if s.count(',') and s.count('.'):
        # assume comma thousands
        s = s.replace(',', '')
    elif s.count(',') and not s.count('.'):
        # assume comma decimal
        s = s.replace(',', '.')
    try:
        return Decimal(s)
    except InvalidOperation:
        return None


vendors = pd.read_excel(VENDORS_PATH, dtype={'id': str, 'name': str, 'iban': str}).fillna('')
vendor_rows = vendors.to_dict('records')

# Build normalized index; keep collision-safe list
vendors_by_norm = {}
for r in vendor_rows:
    nn = norm_name(r.get('name', ''))
    vendors_by_norm.setdefault(nn, []).append(r)

vendor_name_choices = [r.get('name', '') for r in vendor_rows]

pos = pd.read_csv(PO_PATH, dtype={'po_number': str, 'vendor_id': str, 'amount': str}).fillna('')
po_rows = pos.to_dict('records')
po_by_number = {}
for r in po_rows:
    po = (r.get('po_number') or '').strip()
    if not po:
        continue
    po_by_number[po] = {
        'vendor_id': (r.get('vendor_id') or '').strip(),
        'amount': parse_money(str(r.get('amount') or '').strip()),
    }


def match_vendor(vendor_name_raw: str):
    qn = norm_name(vendor_name_raw)
    if not qn or len(qn) < 3:
        return {'decision': 'UNKNOWN', 'vendor': None}

    exact_candidates = vendors_by_norm.get(qn)
    if exact_candidates:
        if len(exact_candidates) == 1:
            return {'decision': 'MATCH', 'vendor': exact_candidates[0]}
        # collision: treat as ambiguous
        return {'decision': 'AMBIGUOUS', 'vendor': None}

    # Fuzzy match (conservative)
    results = process.extract(qn, vendor_name_choices, scorer=fuzz.WRatio, limit=2)
    if not results:
        return {'decision': 'UNKNOWN', 'vendor': None}

    best_name, best_score, best_idx = results[0]
    runner_score = results[1][1] if len(results) > 1 else 0

    THRESH = 90
    MARGIN = 3
    if best_score >= THRESH and (best_score - runner_score) >= MARGIN:
        return {'decision': 'MATCH', 'vendor': vendor_rows[best_idx]}
    if best_score >= THRESH:
        return {'decision': 'AMBIGUOUS', 'vendor': None}
    return {'decision': 'UNKNOWN', 'vendor': None}


rx_from = re.compile(r'^From:\s*(.+?)\s*$', re.IGNORECASE | re.MULTILINE)
rx_total = re.compile(r'^Total\s*\$?\s*([0-9][0-9,]*\.[0-9]{2})\s*$', re.IGNORECASE | re.MULTILINE)
rx_iban = re.compile(r'^Payment\s+IBAN:\s*(.+?)\s*$', re.IGNORECASE | re.MULTILINE)
rx_po = re.compile(r'^PO\s+Number:\s*(.+?)\s*$', re.IGNORECASE | re.MULTILINE)

report = []

with pdfplumber.open(PDF_PATH) as pdf:
    for idx, page in enumerate(pdf.pages, start=1):
        text = page.extract_text() or ''

        vendor_name = (rx_from.search(text).group(1).strip() if rx_from.search(text) else '').strip()
        iban = (rx_iban.search(text).group(1).strip() if rx_iban.search(text) else '').strip()
        po_number = (rx_po.search(text).group(1).strip() if rx_po.search(text) else '').strip() or None

        amt_s = rx_total.search(text).group(1).strip() if rx_total.search(text) else None
        inv_amount_dec = parse_money(amt_s) if amt_s else None

        m = match_vendor(vendor_name)
        matched_vendor = m['vendor']

        reason = None

        # 1) Unknown Vendor
        if m['decision'] != 'MATCH':
            reason = 'Unknown Vendor'

        # 2) IBAN Mismatch
        elif iban and matched_vendor and norm_iban(iban) != norm_iban(matched_vendor.get('iban', '')):
            reason = 'IBAN Mismatch'

        # Remaining checks depend on PO existence
        elif po_number is not None:
            po_rec = po_by_number.get(po_number)

            # 3) Invalid PO
            if po_rec is None:
                reason = 'Invalid PO'

            else:
