                po_amount = po_rec.get('amount')
                if inv_amount_dec is not None and po_amount is not None:
                    if (inv_amount_dec - po_amount).copy_abs() > Decimal('0.01'):
                        reason = 'Amount Mismatch'

                # 5) Vendor Mismatch
                if reason is None and matched_vendor is not None:
                    inv_vendor_id = (matched_vendor.get('id') or '').strip()
                    po_vendor_id = (po_rec.get('vendor_id') or '').strip()
                    if inv_vendor_id and po_vendor_id and inv_vendor_id != po_vendor_id:
                        reason = 'Vendor Mismatch'

        if reason is not None:
            report.append({
                'invoice_page_number': idx,
                'vendor_name': vendor_name or None,
                'invoice_amount': float(inv_amount_dec.quantize(Decimal('0.01'))) if inv_amount_dec is not None else None,
                'iban': iban or None,
                'po_number': po_number,
                'reason': reason,
            })

with open(OUT_PATH, 'w', encoding='utf-8') as f:
    json.dump(report, f, indent=2)

print('flagged', len(report), 'written to', OUT_PATH)
print('first 5 flagged:')
